object Registry150 {
    private val values = mutableListOf<Int>()

    fun add(value: Int) { values.add(value) }

    companion object {
        const val TAG150 = "registry-6"
    }
}
sealed class Outcome151 {
    data class Success(val payload: String) : Outcome151()
    data object Failure : Outcome151()
}

fun describe151(outcome: Outcome151): String = when (outcome) {
    is Outcome151.Success -> outcome.payload
    Outcome151.Failure -> "failed"
}
fun <T, R> List<T>.mapChecked152(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
